#include <Arduino.h>
void worker(void*) {
    for (;;) { Serial.println("worker tick"); vTaskDelay(pdMS_TO_TICKS(1000)); }
}
void setup() {
    Serial.begin(115200);
    xTaskCreate(worker, "worker", 2048, nullptr, 1, nullptr);
}
void loop() { vTaskDelay(pdMS_TO_TICKS(1000)); }

#include <Arduino.h>
void task(void*) { for (;;) { Serial.println("tick"); vTaskDelay(pdMS_TO_TICKS(500)); } }
void setup() { Serial.begin(115200); xTaskCreate(task, "sample", 2048, nullptr, 1, nullptr); }
void loop() { vTaskDelay(pdMS_TO_TICKS(1000)); }
